  "fine_trace": [
    {
      "step": 1,
      "file": "parser.c",
      "function": "xmlParseDocTypeDecl",
      "line": 7971,
      "var": "URI = xmlParseExternalID(ctxt, &publicId, 1)",
      "code": "URI = xmlParseExternalID(ctxt, &publicId, 1);",
      "note": "The crafted DOCTYPE declaration contains a PUBLIC external identifier, so document type parsing passes attacker-controlled parser input to ExternalID parsing in strict mode.",
      "role": "source"
    },
    {
      "step": 2,
      "file": "parser.c",
      "function": "xmlParseExternalID",
      "line": 4782,
      "var": "*publicId",
      "code": "*publicId = xmlParsePubidLiteral(ctxt);",
      "note": "The PUBLIC branch consumes the PubidLiteral from the input and stores the returned heap buffer through publicId.",
      "role": "intermediate"
    },
    {
      "step": 3,
      "file": "parser.c",
      "function": "xmlParsePubidLiteral",
      "line": 4431,
      "var": "buf",
      "code": "buf = xmlMalloc(size);",
      "note": "The public identifier buffer is allocated with the initial size XML_PARSER_BUFFER_SIZE while len starts at zero.",
      "role": "intermediate"
    },
    {
      "step": 4,
      "file": "parser.c",
      "function": "xmlParsePubidLiteral",
      "line": 4439,
      "var": "len + 1 >= size",
      "code": "if (len + 1 >= size) {",
      "note": "When the attacker-controlled public identifier reaches the end of the initial allocation, the parser enters the growth path before appending the next character.",
      "role": "intermediate"
    },
    {
      "step": 5,
      "file": "parser.c",
      "function": "xmlParsePubidLiteral",
      "line": 4449,
      "var": "tmp = xmlRealloc(buf, size)",
      "code": "tmp = xmlRealloc(buf, size);",
      "note": "The code computes newSize but reallocates with the old size, so the backing allocation remains size bytes even though the logical capacity will be increased.",
      "role": "root_cause"
    },
    {
      "step": 6,
      "file": "parser.c",
      "function": "xmlParsePubidLiteral",
      "line": 4456,
      "var": "size = newSize",
      "code": "size = newSize;",
      "note": "The logical capacity is updated to newSize, allowing subsequent loop iterations to believe there is room beyond the actual old allocation.",
      "role": "intermediate"
    },
    {
      "step": 7,
      "file": "parser.c",
      "function": "xmlParsePubidLiteral",
      "line": 4458,
      "var": "buf[len++]",
      "code": "buf[len++] = cur;",
      "note": "After the growth path leaves the actual allocation unchanged, copying attacker-controlled PubidLiteral bytes at len equal to the old capacity writes one byte past the heap buffer.",
      "role": "sink"
    }
  ],
  "vuln_logic": {
    "source": {
      "file": "parser.c",
      "function": "xmlParseDocTypeDecl",
      "line": 7971,
      "operands": ["URI", "xmlParseExternalID(ctxt, &publicId, 1)"]
    },
    "root_cause": {
      "file": "parser.c",
      "function": "xmlParsePubidLiteral",
      "line": 4449,
      "operands": ["tmp", "xmlRealloc(buf, size)", "newSize"],
      "relation": {"op": "eq", "left": "xmlRealloc(buf, size)", "right": "xmlRealloc(buf, newSize)"}
    },
    "sink": {
      "file": "parser.c",
      "function": "xmlParsePubidLiteral",
      "line": 4458,
      "operands": ["buf[len++]", "cur"],
      "relation": {"op": "lt", "left": "len", "right": "size"}
    },
    "propagation": [
      {
        "from": {"file": "parser.c", "function": "xmlParseDocTypeDecl", "line": 7971, "operands": ["URI", "xmlParseExternalID(ctxt, &publicId, 1)"]},
        "to": {"file": "parser.c", "function": "xmlParseExternalID", "line": 4782, "operands": ["*publicId", "xmlParsePubidLiteral(ctxt)"]},
        "type": "control",
        "via": ["ctxt", "&publicId"],
        "relation": {"op": "same_object", "left": "&publicId", "right": "publicId"}
      },
      {
        "from": {"file": "parser.c", "function": "xmlParseExternalID", "line": 4782, "operands": ["*publicId", "xmlParsePubidLiteral(ctxt)"]},
        "to": {"file": "parser.c", "function": "xmlParsePubidLiteral", "line": 4431, "operands": ["buf", "xmlMalloc(size)"]},
        "type": "data",
        "via": ["ctxt", "CUR"],
        "relation": {"op": "same_object", "left": "ctxt", "right": "ctxt"}
      },
      {
        "from": {"file": "parser.c", "function": "xmlParsePubidLiteral", "line": 4431, "operands": ["buf", "xmlMalloc(size)"]},
        "to": {"file": "parser.c", "function": "xmlParsePubidLiteral", "line": 4449, "operands": ["tmp", "xmlRealloc(buf, size)", "newSize"]},
        "type": "data",
        "via": ["buf", "size"],
        "relation": {"op": "same_object", "left": "buf", "right": "buf"}
      },
      {
        "from": {"file": "parser.c", "function": "xmlParsePubidLiteral", "line": 4449, "operands": ["tmp", "xmlRealloc(buf, size)", "newSize"]},
        "to": {"file": "parser.c", "function": "xmlParsePubidLiteral", "line": 4458, "operands": ["buf[len++]", "cur"]},
        "type": "data",
        "via": ["buf", "size", "newSize", "len"],
        "relation": {"op": "same_object", "left": "buf", "right": "buf"}
      }
    ]
  }
